// Configure Open-VSX search query (zero API keys required)
const query = 'mcp';
const size = 5;
const requestUrl = `https://open-vsx.org/api/-/search?query=${encodeURIComponent(query)}&size=${size}&sortBy=downloadCount&sortOrder=desc`;
return [{ json: { query, size, requestUrl } }];

// Extract top extensions from Open-VSX search & prepare review endpoints
const payload = $input.first().json || {};
const exts = Array.isArray(payload.extensions) ? payload.extensions : [];

return exts.slice(0, 5).map((e) => ({
  json: {
    extensionId: `${e.namespace}.${e.name}`,
    namespace: e.namespace,
    name: e.name,
    displayName: e.displayName || e.name,
    downloadCount: Number(e.downloadCount || 0),
    averageRating: e.averageRating ?? null,
    reviewCount: Number(e.reviewCount || 0),
    homepage: e.homepage || null,
    repository: e.repository || null,
    reviewsUrl: `https://open-vsx.org/api/${encodeURIComponent(e.namespace)}/${encodeURIComponent(e.name)}/reviews`,
  },
}));

// Filter <= 3-star Open-VSX developer bug & UX reviews
const revResponses = $input.all();
const extMeta = $('Extract Extensions & Review URLs').all();
const out = [];

for (let i = 0; i < revResponses.length; i++) {
  const data = revResponses[i].json || {};
  const meta = (extMeta[i] && extMeta[i].json) ? extMeta[i].json : {};
  const reviews = Array.isArray(data.reviews) ? data.reviews : [];
  const lowReviews = reviews.filter((r) => Number(r.rating || 5) <= 3);

  out.push({
    json: {
      extensionId: meta.extensionId,
      displayName: meta.displayName,
      downloadCount: meta.downloadCount,
      averageRating: meta.averageRating,
      totalReviews: meta.reviewCount,
      lowStarReviewCount: lowReviews.length,
      repository: meta.repository,
      recentLowReviews: lowReviews.slice(0, 5).map((r) => ({
        rating: r.rating,
        user: (r.user && r.user.loginName) || null,
        comment: String(r.comment || '').slice(0, 240),
        timestamp: r.timestamp || null,
      })),
      agentSummary: `${meta.extensionId}: ${meta.downloadCount.toLocaleString('en-US')} installs, ${lowReviews.length} <=3-star reviews`,
    },
  });
}

return out.length ? out : [{ json: { status: 'no_extensions_found' } }];
